/* Palette: #1e1e2f (bg), #2a2a40 (card), #e0e0e0 (text), #6c63ff (primary), #ff6b6b (danger) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  color: #e0e0e0;
}

.card {
  background: #2a2a40;
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 500px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  text-align: center;
  letter-spacing: 1px;
  color: #6c63ff;
  text-shadow: 2px 2px 0 #1e1e2f;
}

.input-group {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}

input[type="text"] {
  flex: 1;
  padding: 12px;
  border: 2px solid #3a3a5a;
  border-radius: 8px;
  background: #1e1e2f;
  color: #e0e0e0;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

input[type="text"]:focus {
  border-color: #6c63ff;
}

button {
  padding: 12px 16px;
  border: none;
  border-radius: 8px;
  background: #6c63ff;
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}

button:hover {
  background: #5a52d5;
}

button:focus-visible {
  outline: 3px solid #e0e0e0;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

#task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #1e1e2f;
  padding: 12px;
  border-radius: 8px;
  border: 2px solid #3a3a5a;
  flex-wrap: wrap;
}

.task-name {
  flex: 1 1 120px;
  font-weight: 500;
  word-break: break-word;
}

.task-time {
  font-variant-numeric: tabular-nums;
  font-size: 1.25rem;
  font-weight: 700;
  color: #6c63ff;
  min-width: 70px;
  text-align: right;
}

.task-actions {
  display: flex;
  gap: 8px;
}

.task-actions button {
  padding: 8px 12px;
  font-size: 0.875rem;
}

.start-btn {
  background: #6c63ff;
}

.start-btn:hover {
  background: #5a52d5;
}

.stop-btn {
  background: #ff6b6b;
}

.stop-btn:hover {
  background: #e05555;
}

.remove-btn {
  background: #3a3a5a;
}

.remove-btn:hover {
  background: #4a4a6a;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .task-item {
    flex-direction: column;
    align-items: stretch;
  }
  .task-time {
    text-align: left;
  }
  .task-actions {
    justify-content: flex-end;
  }
}

const taskNameInput = document.getElementById('task-name');
const addBtn = document.getElementById('add-btn');
const taskList = document.getElementById('task-list');

let tasks = [];
let runningTaskId = null;
let intervalId = null;

function formatTime(seconds) {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
}

function render() {
  taskList.innerHTML = '';
  tasks.forEach(task => {
    const li = document.createElement('li');
    li.className = 'task-item';
    li.dataset.id = task.id;

    const nameSpan = document.createElement('span');
    nameSpan.className = 'task-name';
    nameSpan.textContent = task.name;

    const timeSpan = document.createElement('span');
    timeSpan.className = 'task-time';
    timeSpan.textContent = formatTime(task.elapsed);

    const actionsDiv = document.createElement('div');
    actionsDiv.className = 'task-actions';

    const startStopBtn = document.createElement('button');
    startStopBtn.type = 'button';
    startStopBtn.className = task.isRunning ? 'stop-btn' : 'start-btn';
    startStopBtn.textContent = task.isRunning ? 'Stop' : 'Start';
    startStopBtn.setAttribute('aria-label', `${task.isRunning ? 'Stop' : 'Start'} timer for ${task.name}`);
    startStopBtn.addEventListener('click', () => toggleTask(task.id));

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'remove-btn';
    removeBtn.textContent = 'Remove';
    removeBtn.setAttribute('aria-label', `Remove task ${task.name}`);
    removeBtn.addEventListener('click', () => removeTask(task.id));

    actionsDiv.appendChild(startStopBtn);
    actionsDiv.appendChild(removeBtn);

    li.appendChild(nameSpan);
    li.appendChild(timeSpan);
    li.appendChild(actionsDiv);
    taskList.appendChild(li);
  });
}

function addTask() {
  const name = taskNameInput.value.trim();
  if (!name) return;
  const task = {
    id: Date.now() + Math.random(),
    name,
    elapsed: 0,
    isRunning: false
  };
  tasks.push(task);
  taskNameInput.value = '';
  render();
}

function toggleTask(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  if (task.isRunning) {
    task.isRunning = false;
    if (runningTaskId === id) {
      runningTaskId = null;
      clearInterval(intervalId);
      intervalId = null;
    }
  } else {
    if (runningTaskId !== null) {
      const runningTask = tasks.find(t => t.id === runningTaskId);
      if (runningTask) runningTask.isRunning = false;
      clearInterval(intervalId);
    }
    task.isRunning = true;
    runningTaskId = id;
    intervalId = setInterval(() => {
      const currentTask = tasks.find(t => t.id === runningTaskId);
      if (currentTask && currentTask.isRunning) {
        currentTask.elapsed++;
        const timeSpan = document.querySelector(`.task-item[data-id="${currentTask.id}"] .task-time`);
        if (timeSpan) timeSpan.textContent = formatTime(currentTask.elapsed);
      }
    }, 1000);
  }
  render();
}

function removeTask(id) {
  if (runningTaskId === id) {
    clearInterval(intervalId);
    intervalId = null;
    runningTaskId = null;
  }
  tasks = tasks.filter(t => t.id !== id);
  render();
}

addBtn.addEventListener('click', addTask);
taskNameInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

// Initial render
render();
